#define PAS_MAX 180
#define DISTANCE_SURFACE .001
#define DISTANCE_MAX 140.

mat2 tourner(float angle) { float sinus = sin(angle), cosinus = cos(angle); return mat2(cosinus, -sinus, sinus, cosinus); }

float hacher(vec3 position) {
    position = fract(position * 0.1031);
    position += dot(position, position.yzx + 33.33);
    return fract((position.x + position.y) * position.z);
}

float bruit3D(vec3 position) {
    vec3 indexEntier = floor(position);
    vec3 fraction = fract(position);
    fraction = fraction * fraction * (3.0 - 2.0 * fraction);
    return mix(mix(mix(hacher(indexEntier + vec3(0, 0, 0)), hacher(indexEntier + vec3(1, 0, 0)), fraction.x),
                   mix(hacher(indexEntier + vec3(0, 1, 0)), hacher(indexEntier + vec3(1, 1, 0)), fraction.x), fraction.y),
               mix(mix(hacher(indexEntier + vec3(0, 0, 1)), hacher(indexEntier + vec3(1, 0, 1)), fraction.x),
                   mix(hacher(indexEntier + vec3(0, 1, 1)), hacher(indexEntier + vec3(1, 1, 1)), fraction.x), fraction.y), fraction.z);
}

float bruitFractal(vec3 position) {
    float valeur = 0.0;
    float amplitude = 0.5;
    for (int iters = 0; iters < 5; iters++) {
        valeur += amplitude * bruit3D(position);
        position = position * 2.5;
        amplitude *= 0.5;
    }
    return valeur;
}

vec3 obtenirCouleurCiel(vec3 directionRayon, vec3 directionSoleil) {
    float intensiteSoleil = max(dot(directionRayon, directionSoleil), 0.0);
    vec3 couleurCiel = vec3(0.1, 0.3, 0.6) - directionRayon.y * 0.4;
    couleurCiel = mix(couleurCiel, vec3(0.5, 0.7, 0.9), pow(1.0 - max(directionRayon.y, 0.0), 4.0));
    couleurCiel += vec3(1.0, 0.6, 0.3) * pow(intensiteSoleil, 12.0);
    couleurCiel += vec3(1.0, 0.9, 0.7) * pow(intensiteSoleil, 300.0);
    return couleurCiel;
}

float densiteNuage(vec3 position) {
    vec3 posAnimee = position * 0.1 + vec3(0.0, 0.0, iTime * 0.1);
    float densiteBrute = bruitFractal(posAnimee);
    densiteBrute = smoothstep(0.4, 0.8, densiteBrute);
    return densiteBrute * smoothstep(10.0, 30.0, position.y) * smoothstep(80.0, 40.0, position.y);
}

vec3 calculerNuages(vec3 couleurFond, vec3 origineRayon, vec3 directionRayon, vec3 directionSoleil) {
    float pasLongueur = 1.5;
    float distanceParcourue = 0.0;
    float transmittance = 1.0;
    vec3 couleurNuage = vec3(0.0);
    if(directionRayon.y > 0.0) {
        float distanceLimite = 150.0;
        for(int iters = 0; iters < 32; iters++) {
            vec3 positionCourante = origineRayon + directionRayon * distanceParcourue;
            float densite = densiteNuage(positionCourante);
            if(densite > 0.01) {
                float ombre = densiteNuage(positionCourante + directionSoleil * 1.5);
                float lumiere = smoothstep(0.0, 1.0, densite - ombre);
                vec3 ambiante = mix(vec3(0.4, 0.5, 0.6), vec3(1.0), lumiere);
                couleurNuage += transmittance * densite * ambiante;
                transmittance *= 1.0 - densite * 0.5;
                if(transmittance < 0.02) break;
            }
            distanceParcourue += pasLongueur;
            if(distanceParcourue > distanceLimite) break;
        }
    }
    return mix(couleurFond, couleurNuage + couleurFond * transmittance, 1.0 - transmittance);
}

vec3 obtenirTrajectoire(float temps) {
    float tempsEchelle = temps * 0.15; 
    float posX = sin(tempsEchelle * 2.1) * 22.0 + cos(tempsEchelle * 0.9) * 11.0;
    float posY = cos(tempsEchelle * 1.7) * 14.0 + sin(tempsEchelle * 1.2) * 9.0 + 15.0;
    float posZ = temps * 10.0; 
    return vec3(posX, posY, posZ);
}

void obtenirRepere(float temps, out vec3 position, out vec3 vecteurTangente, out vec3 vecteurNormale, out vec3 vecteurBinormale) {
    position = obtenirTrajectoire(temps);
    float deltaTemps = 0.05;
    vecteurTangente = normalize(obtenirTrajectoire(temps + deltaTemps) - position);
    vec3 vecteurHaut = vec3(0, 1, 0);
    vec3 vecteurCote = normalize(cross(vecteurTangente, vecteurHaut));
    float inclinaison = sin(temps * 0.12) * 1.4; 
    vecteurHaut = normalize(vecteurHaut + vecteurCote * inclinaison); 
    vecteurBinormale = normalize(cross(vecteurTangente, vecteurHaut));
    vecteurNormale = cross(vecteurBinormale, vecteurTangente);
}

float distanceBoite(vec3 position, vec3 dimensions) {
    vec3 ecart = abs(position) - dimensions;
    return length(max(ecart, 0.0)) + min(max(ecart.x, max(ecart.y, ecart.z)), 0.0);
}

float carteDistance(vec3 position) {
    float tempsZ = position.z / 10.0; 
    vec3 posRepere, vecteurTangente, vecteurNormale, vecteurBinormale;
    for(int iters = 0; iters < 3; iters++) {
        obtenirRepere(tempsZ, posRepere, vecteurTangente, vecteurNormale, vecteurBinormale);
        tempsZ += dot(position - posRepere, vecteurTangente) / 10.0;
    }
    float hauteurTerrain = posRepere.y - 18.0 + cos(position.x * 0.15) * sin(position.z * 0.12) * 4.0;
    float terrain = position.y - hauteurTerrain;
    vec3 ecartPosition = position - posRepere;
    vec3 positionLocale = vec3(dot(ecartPosition, vecteurBinormale), dot(ecartPosition, vecteurNormale), dot(ecartPosition, vecteurTangente));
    float railGauche = length(positionLocale.xy - vec2(0.8, 0.0)) - 0.15;
    float railDroit = length(positionLocale.xy - vec2(-0.8, 0.0)) - 0.15;
    float rails = min(railGauche, railDroit);
    vec3 posTraverse = positionLocale;
    float pasZTraverse = 3.0; 
    posTraverse.z = mod(posTraverse.z + pasZTraverse * 0.5, pasZTraverse) - pasZTraverse * 0.5;
    float traverses = distanceBoite(posTraverse - vec3(0.0, -0.25, 0.0), vec3(1.2, 0.1, 0.4));
    float distancePylone = 50.0; 
    float indexPylone = floor((position.z + distancePylone * 0.5) / distancePylone) * distancePylone / 10.0;
    vec3 posPylone, tangentePylone, normalePylone, binormalePylone;
    obtenirRepere(indexPylone, posPylone, tangentePylone, normalePylone, binormalePylone);
    vec3 ecartPylone = position - posPylone;
    vec3 posLocalePylone = vec3(dot(ecartPylone, binormalePylone), dot(ecartPylone, normalePylone), dot(ecartPylone, tangentePylone));
    float poutre = distanceBoite(posLocalePylone - vec3(0.0, -0.8, 0.0), vec3(2.5, 0.4, 0.8));
    float colonne = length(position.xz - posPylone.xz) - 0.7;
    colonne = max(colonne, position.y - (posPylone.y - 1.2)); 
    float structurePylone = min(colonne, poutre);
    float voie = min(rails, traverses);
    return min(terrain, min(voie, structurePylone));
}

vec3 calculerNormale(vec3 position) {
    vec2 decalage = vec2(0.005, 0);
    return normalize(vec3(
        carteDistance(position + decalage.xyy) - carteDistance(position - decalage.xyy),
        carteDistance(position + decalage.yxy) - carteDistance(position - decalage.yxy),
        carteDistance(position + decalage.yyx) - carteDistance(position - decalage.yyx)
    ));
}

float dessinerGlissiere(vec2 coordonneesUv, float valeurGlissiere) {
    float elementGlissiere = 0.0;
    vec2 posGlissiere = coordonneesUv - vec2(-0.85, 0.0);
    float fond = smoothstep(0.01, 0.0, abs(posGlissiere.x) - 0.005) * smoothstep(0.5, 0.49, abs(posGlissiere.y));
    float curseur = smoothstep(0.03, 0.02, length(posGlissiere - vec2(0.0, mix(-0.4, 0.4, valeurGlissiere))));
    return max(fond * 0.5, curseur);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float facteurVitesse = (iMouse.z > 0.5) ? clamp((iMouse.y / iResolution.y - 0.1) / 0.8, 0.0, 1.0) : 0.5;
    float vitesseCalculee = mix(5.0, 10.0, facteurVitesse);
    float tempsTotal = iTime * vitesseCalculee; 

    vec3 origineRayon, vecteurTangente, vecteurNormale, vecteurBinormale;
    obtenirRepere(tempsTotal, origineRayon, vecteurTangente, vecteurNormale, vecteurBinormale);
    origineRayon += vecteurNormale * 1.6; 

    vec3 directionSoleil = normalize(vec3(0.5, 0.7, -0.4));
    vec3 directionRayon = normalize(vecteurTangente * 1.2 + uv.x * vecteurBinormale + uv.y * vecteurNormale);
    vec3 couleurFin = obtenirCouleurCiel(directionRayon, directionSoleil);
    couleurFin = calculerNuages(couleurFin, origineRayon, directionRayon, directionSoleil);

    float distanceMarchee = 0.0;
    for(int iters = 0; iters < PAS_MAX; iters++) {
        float res = carteDistance(origineRayon + directionRayon * distanceMarchee);
        if(res < DISTANCE_SURFACE || distanceMarchee > DISTANCE_MAX) break;
        distanceMarchee += res;
    }

    if(distanceMarchee < DISTANCE_MAX) {
        vec3 posImpact = origineRayon + directionRayon * distanceMarchee;
        vec3 normaleSurface = calculerNormale(posImpact);
        float diffusion = clamp(dot(normaleSurface, directionSoleil), 0.0, 1.0);
        float speculaire = pow(clamp(dot(reflect(-directionSoleil, normaleSurface), -directionRayon), 0.0, 1.0), 40.0);
        float occlusionAmbiante = clamp(carteDistance(posImpact + normaleSurface * 0.8) / 0.8, 0.0, 1.0);

        float tempsLocalZ = posImpact.z / 10.0;
        vec3 posRepere, tangentePylone, normalePylone, binormalePylone;
        obtenirRepere(tempsLocalZ, posRepere, tangentePylone, normalePylone, binormalePylone);
        vec3 ecartPosition = posImpact - posRepere;
        vec3 positionLocale = vec3(dot(ecartPosition, binormalePylone), dot(ecartPosition, normalePylone), dot(ecartPosition, tangentePylone));

        vec3 albedoSurface = vec3(0.2); 
        if(posImpact.y < posRepere.y - 5.0) {
            albedoSurface = vec3(0.1, 0.15, 0.05);
        } else {
            float pasZTraverse = 3.0;
            float moduloZ = abs(mod(positionLocale.z + pasZTraverse * 0.5, pasZTraverse) - pasZTraverse * 0.5);
            if(moduloZ < 0.45 && positionLocale.y < -0.1 && positionLocale.y > -0.6) {
                albedoSurface = vec3(0.12, 0.08, 0.05);
            } else if (abs(positionLocale.x) > 0.6 && abs(positionLocale.y) < 0.3) {
                albedoSurface = vec3(0.4, 0.42, 0.45);
            } else {
                albedoSurface = vec3(0.65, 0.1, 0.1);
            }
        }
        vec3 eclairage = albedoSurface * (diffusion + 0.2) * occlusionAmbiante + speculaire * 0.4;
        couleurFin = mix(eclairage, obtenirCouleurCiel(directionRayon, directionSoleil), 1.0 - exp(-0.00015 * distanceMarchee * distanceMarchee));
    }

    couleurFin = pow(couleurFin, vec3(0.4545)); 
    couleurFin *= 1.0 - dot(uv, uv) * 0.3;

    float masqueGlissiere = dessinerGlissiere(uv, facteurVitesse);
    couleurFin = mix(couleurFin, vec3(1.0), masqueGlissiere);

    fragColor = vec4(couleurFin, 1.0);
}
